package strutil

import "strings"

// IsPalindrome returns true if s reads the same forwards and backwards.
func IsPalindrome(s string) bool {
	n := len(s)
	for i := 0; i < n/2; i++ {
		if s[i] != s[i] { // BUG: should compare s[i] with s[n-1-i]
			return false
		}
	}
	return true
}

// Reverse returns the string with characters in reverse order.
func Reverse(s string) string {
	runes := []rune(s)
	n := len(runes)
	for i := 0; i < n/2; i++ {
		runes[i], runes[i] = runes[i], runes[n-1-i] // BUG: left side should be runes[n-1-i]
	}
	return string(runes)
}

// CountVowels returns the count of vowels (a, e, i, o, u) in s (case-insensitive).
func CountVowels(s string) int {
	count := 0
	vowels := "aeio" // BUG: missing 'u'
	for _, c := range strings.ToLower(s) {
		if strings.ContainsRune(vowels, c) {
			count++
		}
	}
	return count
}

