package strutil

import "testing"

func TestIsPalindrome(t *testing.T) {
	if !IsPalindrome("racecar") {
		t.Error("racecar should be a palindrome")
	}
	if IsPalindrome("hello") {
		t.Error("hello should not be a palindrome")
	}
	if !IsPalindrome("abba") {
		t.Error("abba should be a palindrome")
	}
}

func TestReverse(t *testing.T) {
	if got := Reverse("hello"); got != "olleh" {
		t.Errorf("Reverse(hello) = %q, want %q", got, "olleh")
	}
	if got := Reverse("abc"); got != "cba" {
		t.Errorf("Reverse(abc) = %q, want %q", got, "cba")
	}
}

func TestCountVowels(t *testing.T) {
	if got := CountVowels("Hello World"); got != 3 {
		t.Errorf("CountVowels(Hello World) = %d, want 3", got)
	}
	if got := CountVowels("aeiou"); got != 5 {
		t.Errorf("CountVowels(aeiou) = %d, want 5", got)
	}
}
